import { IoC } from "./shared/ioc";
import { composeAPI } from "./main";
import { WorkspacesFactoryFunction } from "../workspaces";

/* eslint-disable @typescript-eslint/no-explicit-any */
const factoryFunction: WorkspacesFactoryFunction = async (io: any): Promise<void> => {

    const ioc = new IoC(io.agm, io.windows, io.layouts, io.contexts);

    const actualWindowId = io.interop.instance.windowId;

    await ioc.initiate(actualWindowId);

    io.workspaces = composeAPI(io, ioc);
};

// attach to window object
if (typeof window !== "undefined") {
    /* eslint-disable @typescript-eslint/no-explicit-any */
    (window as any).IOWorkspaces = factoryFunction;
}

export default factoryFunction;
