import './App.css';
import './index.css';
import { useIOConnect } from "@interopio/react-hooks";
import Workspaces from "@interopio/workspaces-ui-react";
import "@interopio/workspaces-ui-react/dist/styles/workspaces.css"

const App = () => {
    useIOConnect((io: any) => {
        (window as any).io = io;
        (window as any).glue = io;
      });

    return (
        <Workspaces />
    );
}

export default App;