    public async removeChild(predicate: (child: IOConnectWorkspaces.WorkspaceElement) => boolean): Promise<void> {
        checkThrowCallback(predicate);
        const child = this.children.find(predicate);
        if (!child) {
            return;
        }
        await child.close();
        await this.refreshReference();
    }

    public async remove(predicate: (child: IOConnectWorkspaces.WorkspaceElement) => boolean): Promise<void> {
        checkThrowCallback(predicate);
        const controller = getData(this).controller;

        const child = controller.iterateFindChild(this.children, predicate);

        await child.close();

        await this.refreshReference();
    }

    public async focus(): Promise<void> {
        await getData(this).controller.focusItem(this.id);
        await this.refreshReference();
    }

    public async close(): Promise<void> {
        const controller = getData(this).controller;

        const workspaces = await getData(this).frame.workspaces();

        // should close the frame only if the frame is NOT a platform
        const platformFrameId = (await controller.getPlatformFrameId()).id;

        const shouldCloseFrame = workspaces.length === 1 &&
            workspaces.every((wsp) => wsp.id === this.id) &&
            platformFrameId !== this.frame.id;

        if (shouldCloseFrame) {
            return this.frame.close();
        }

        await controller.closeItem(this.id);
    }

