    public getBox(predicate: (box: IOConnectWorkspaces.WorkspaceBox) => boolean): IOConnectWorkspaces.WorkspaceBox {
        checkThrowCallback(predicate);
        const children = getData(this).children;
        const controller = getData(this).controller;

        return controller.iterateFindChild(children, (child) => child.type !== "window" && predicate(child)) as IOConnectWorkspaces.WorkspaceBox;
    }

    public getAllBoxes(predicate?: (parent: IOConnectWorkspaces.WorkspaceBox) => boolean): IOConnectWorkspaces.WorkspaceBox[] {
        checkThrowCallback(predicate, true);
        const children = getData(this).children;
        const controller = getData(this).controller;

        const allParents = controller.iterateFilterChildren(children, (child) => child.type !== "window") as IOConnectWorkspaces.WorkspaceBox[];

        if (!predicate) {
            return allParents;
        }

        return allParents.filter(predicate);
    }

