    public async showLoadingAnimation(): Promise<void> {
        const desktopGlobal = (window as any).glue42gd || (window as any).iodesktop;

        if (!desktopGlobal) {
            throw new Error("Not supported in IO Connect Browser");
        }

        await getData(this).controller.showWorkspaceLoadingAnimation(this.id);
    }

